fn insert_before_each(arr: &Vec<i32>, elem: i32) -> Vec<i32> {
    // Pre‐allocate a vector of the required size (2 * arr.len())
    let mut result = Vec::with_capacity(arr.len() * 2);

    // For each element in the input, push `elem` then the element itself.
    for &value in arr.iter() {
        result.push(elem);
        result.push(value);
    }

    result
}

